<script setup>import {ElMessageBox} from 'element-plus';import {ref,onMounted} from 'vue';import {api,invoke} from '../bridge/jcefBridge';import PageShell from '../components/common/PageShell.vue';const rows=ref([]);const load=()=>api('sessions.list').then(x=>rows.value=x);async function rename(x){const {value}=await ElMessageBox.prompt('输入新的会话名称','重命名',{inputValue:x.title});await api('session.rename',{id:x.id,title:value});load()}async function remove(x){await ElMessageBox.confirm(`确定删除会话 ${x.title}？`,'删除',{type:'warning'});await api('session.delete',{id:x.id});load()}onMounted(load)</script>
<template><PageShell title="会话管理"><template #actions><el-button type="primary" @click="invoke('session.new').then(load)">新建会话</el-button></template><el-table :data="rows" height="100%"><el-table-column prop="title" label="名称"/><el-table-column prop="agentId" label="Agent"/><el-table-column prop="updatedAt" label="更新时间"/><el-table-column width="160"><template #default="{row}"><el-button link @click="rename(row)">重命名</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></PageShell></template>
